    { id: 'q101', p: ['bt1'], type: 'num', lvl: 2, q: 'Two waves of 300 Hz and 304 Hz are heard together. The ear hears a sound of frequency about:', o: ['4 Hz', '604 Hz', '300 Hz with 2 beats per second', '302 Hz with 4 beats per second'], a: 3, e: 'Average frequency, difference beats.', sol: ['Average = (300 + 304)/2 = 302 Hz', 'Beat frequency = 304 − 300 = 4 Hz', 'Waxing and waning 4 times a second', 'Answer: 302 Hz with 4 beats/s'] },
    { id: 'q102', p: ['e146'], type: 'st', lvl: 2, st: ['Increasing the tension of a string increases its frequency.', 'In Example 14.6, ν_B was greater than ν_A.'], a: 2, e: 'ν_B < ν_A.' },
    { id: 'q103', p: ['sm1'], type: 'mcq', lvl: 1, q: 'Mechanical waves are governed by:', o: ['Newton\'s laws', 'Maxwell\'s equations', 'Kepler\'s laws', 'Ohm\'s law'], a: 0, e: 'Summary 1.' },
    { id: 'q104', p: ['sm2'], type: 'mcq', lvl: 2, q: 'For a pipe of length L closed at one end, the fundamental frequency is:', o: ['v/2L', 'v/4L', 'v/L', '3v/4L'], a: 1, e: 'Summary 15.' }
